from decimal import Decimal

from django import forms

from .models import Patient, PatientTest, Test, TestResult


class PatientForm(forms.ModelForm):
    class Meta:
        model = Patient
        # The LIMS ID is generated by the model, not manually entered by staff.
        fields = [
            "national_id",
            "first_name",
            "middle",
            "last_name",
            "date_of_birth",
            "gender",
            "blood_group",
            "phone",
            "email",
            "address",
            "emergency_contact",
            "notes",
        ]
        widgets = {
            "date_of_birth": forms.DateTimeInput(attrs={"type": "datetime-local"}),
            "address": forms.Textarea(attrs={"rows": 2}),
            "notes": forms.Textarea(attrs={"rows": 3}),
        }


class TestForm(forms.ModelForm):
    class Meta:
        model = Test
        fields = [
            "test_code",
            "test_name",
            "department",
            "sample_type",
            "unit",
            "reference_range",
            "price",
            "turnaround_time_hours",
            "instructions",
            "active",
        ]
        widgets = {
            "instructions": forms.Textarea(attrs={"rows": 3}),
            "reference_range": forms.TextInput(),
            "price": forms.NumberInput(attrs={"step": "0.01", "min": "0"}),
            "turnaround_time_hours": forms.NumberInput(attrs={"min": "0", "step": "1"}),
        }


class PatientTestForm(forms.ModelForm):
    class Meta:
        model = PatientTest
        fields = [
            "patient",
            "test",
            "sample_identifier",
            "result_valu",
            "result_text",
            "performed_by",
            "discount_percent",
        ]
        widgets = {
            "patient": forms.Select(attrs={"class": "form-control"}),
            "test": forms.Select(attrs={"class": "form-control"}),
            "sample_identifier": forms.TextInput(attrs={"class": "form-control"}),
            "result_valu": forms.TextInput(attrs={"class": "form-control"}),
            "result_text": forms.Textarea(attrs={"rows": 2, "class": "form-control"}),
            "performed_by": forms.TextInput(attrs={"class": "form-control"}),
            "discount_percent": forms.NumberInput(
                attrs={"step": "0.01", "min": "0", "max": "100", "class": "form-control"}
            ),
        }

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        # Only active catalogue tests should be selectable for new requests.
        self.fields["test"].queryset = Test.objects.filter(active=True).order_by(
            "department", "test_name"
        )

    def clean_discount_percent(self):
        discount = self.cleaned_data.get("discount_percent")
        if discount is None:
            discount = Decimal("0.00")
        if not Decimal("0.00") <= discount <= Decimal("100.00"):
            raise forms.ValidationError("Discount must be between 0 and 100.")
        return discount


class TestResultForm(forms.ModelForm):
    class Meta:
        model = TestResult
        fields = [
            "result_valu",
            "unit",
            "reference_range",
            "wbc",
            "rbc",
            "hemoglobin",
            "hematocrit",
            "platelets",
        ]
        widgets = {
            "result_valu": forms.TextInput(attrs={"class": "form-control"}),
            "unit": forms.TextInput(attrs={"class": "form-control"}),
            "reference_range": forms.TextInput(attrs={"class": "form-control"}),
            "wbc": forms.NumberInput(attrs={"step": "any"}),
            "rbc": forms.NumberInput(attrs={"step": "any"}),
            "hemoglobin": forms.NumberInput(attrs={"step": "any"}),
            "hematocrit": forms.NumberInput(attrs={"step": "any"}),
            "platelets": forms.NumberInput(attrs={"step": "any"}),
        }
